func TestBrainSizeRejectsMissingStore(t *testing.T) {
	if _, _, err := measureBrainSize(filepath.Join(t.TempDir(), "missing")); err == nil {
		t.Fatal("missing store reported as a zero-byte measurement")
	}
}

