	stats := map[string]latencyStats{}
	var warnings []string

	records := 0
	if facts, err := loadFacts(brainDir, branch); err == nil {
		records += len(facts)
	}
	if index, err := loadDocIndex(brainDir); err == nil {
		records += len(index.Records)
	}

	for _, mode := range []retrievalMode{modeLexical, modeHybrid} {
		var samples []float64
		failures := 0
		for _, query := range queries {
			if _, err := retrieveUnified(repoDir, brainDir, branch, query, 20, mode); err != nil {
				failures++
				continue
			}
			for i := 0; i < repeats; i++ {
				start := time.Now()
				_, err := retrieveUnified(repoDir, brainDir, branch, query, 20, mode)
				elapsed := time.Since(start)
				if err != nil {
					failures++
					continue
				}
				samples = append(samples, float64(elapsed.Nanoseconds())/1e6)
			}
		}
		name := retrievalModeName(mode)
		if failures > 0 {
			warnings = append(warnings, fmt.Sprintf("%s: %d retrieval(s) failed and are not in the distribution", name, failures))
		}
		stats[name] = summarizeLatency(samples)
	}
	return stats, records, warnings
}

func summarizeLatency(samples []float64) latencyStats {
	if len(samples) == 0 {
		return latencyStats{}
	}
	sorted := append([]float64(nil), samples...)
	sort.Float64s(sorted)
	var sum float64
	for _, v := range sorted {
		sum += v
	}
	return latencyStats{
		Samples: len(sorted),
		MinMS:   sorted[0],
		P50MS:   percentile(sorted, 0.50),
		P95MS:   percentile(sorted, 0.95),
		P99MS:   percentile(sorted, 0.99),
		MaxMS:   sorted[len(sorted)-1],
		MeanMS:  sum / float64(len(sorted)),
	}
}","merged_ranks":[1,2]},{"rank":2,"score":28.6356,"file_path":"internal/cli/pattern_corpus.go","start_line":405,"end_line":427,"focus_line":411,"snippet_start_line":411,"snippet_end_line":427,"symbol_start_line":411,"symbol_end_line":427,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/pattern_corpus.go:function:validatePatternCorpusReadSafety","symbol_name":"validatePatternCorpusReadSafety","qualified_name":"validatePatternCorpusReadSafety","signature":"func validatePatternCorpusReadSafety(brainDir string) error","signals":["path","body","symbol-name","graph:callers","complete-symbol"],"snippet":"func validatePatternCorpusReadSafety(brainDir string) error {
