	facts, err := loadFacts(brainDir, branch)
	if err != nil {
		return 0, err
	}
	records := len(facts)
	index, err := loadDocIndex(brainDir)
	if err == nil {
		records += len(index.Records)
	} else if !os.IsNotExist(err) {
		return 0, err
	}
	manifest, err := loadBrainManifest(brainDir)
	if err != nil {
		return 0, err
